parameters.jsonBody:
={{ JSON.stringify({
  model: 'claude-opus-4-7',
  max_tokens: 4096,
  system: "You are Florence's image-blueprint generator. Given an ASIN and its ranked objections (most painful → least), draft a slide-by-slide secondary-image brief: one image per objection, in objection-rank order. For each: state the objection it answers, the visual concept, an expected lift band (Low/Medium/High) drawing on the 52-tactic library when relevant. Return Markdown only — no preamble, no JSON wrapper.",
  messages: [{
    role: 'user',
    content: 'ASIN: ' + $json.body.asin + '\n\nContext:\n' + JSON.stringify($json.body.asin_context || {}, null, 2) + '\n\nRanked objections:\n' + JSON.stringify($json.body.ranked_objections || [], null, 2)
  }]
}) }}
